#include <iostream>
#include <string>
#include <vector>
#include <memory>
#include <functional>
#include <unordered_map>
#include <mutex>
#include <algorithm>

enum class Role { ADMIN, USER, GUEST };

struct EmailMessage {
    std::string from;
    std::string to;
    std::string subject;
    std::string body;
    Role sender_role;
};

class AuditLog {
public:
    using LogCallback = std::function<void(const std::string&)>;

    void register_callback(const std::string& event_type, LogCallback cb) {
        std::lock_guard<std::mutex> lock(mtx_);
        callbacks_[event_type].push_back(std::move(cb));
    }

    void emit(const std::string& event_type, const std::string& detail) {
        std::lock_guard<std::mutex> lock(mtx_);
        auto it = callbacks_.find(event_type);
        if (it != callbacks_.end()) {
            for (auto& cb : it->second) {
                cb(detail);
            }
        }
    }

private:
    std::mutex mtx_;
    std::unordered_map<std::string, std::vector<LogCallback>> callbacks_;
};

class RateLimiter {
public:
    explicit RateLimiter(int max_per_window) : max_(max_per_window) {}

    bool allow(const std::string& user) {
        std::lock_guard<std::mutex> lock(mtx_);
        return ++counts_[user] <= max_;
    }

    void reset() {
        std::lock_guard<std::mutex> lock(mtx_);
        counts_.clear();
    }

private:
    int max_;
    std::mutex mtx_;
    std::unordered_map<std::string, int> counts_;
};

class EmailService {
public:
    EmailService(AuditLog& audit, int rate_limit)
        : audit_(audit), limiter_(rate_limit) {
        audit_.register_callback("policy_change", [this](const std::string& detail) {
            handle_policy_change(detail);
        });
    }

    ~EmailService() = default;

    bool send_email(const EmailMessage& msg) {
        if (!check_permission(msg)) {
            audit_.emit("access_denied", msg.from + " -> " + msg.to);
            return false;
        }

        if (!limiter_.allow(msg.from)) {
            audit_.emit("rate_limited", msg.from);
            return false;
        }

        return dispatch(msg);
    }

    void set_restricted_domains(std::vector<std::string> domains) {
        std::lock_guard<std::mutex> lock(domain_mtx_);
        restricted_domains_ = std::make_unique<std::vector<std::string>>(std::move(domains));
    }

private:
    bool check_permission(const EmailMessage& msg) {
        if (msg.sender_role == Role::ADMIN) return true;
        if (msg.sender_role == Role::GUEST) return false;

        std::lock_guard<std::mutex> lock(domain_mtx_);
        if (!restricted_domains_) return true;

        auto domain = extract_domain(msg.to);
        auto& domains_ref = *restricted_domains_;
        return std::find(domains_ref.begin(), domains_ref.end(), domain) == domains_ref.end();
    }

    void handle_policy_change(const std::string& detail) {
        if (detail == "reset_limits") {
            limiter_.reset();
        } else if (detail.substr(0, 8) == "domains:") {
            auto new_domains = parse_domain_list(detail.substr(8));
            restricted_domains_.reset();
            restricted_domains_ = std::make_unique<std::vector<std::string>>(std::move(new_domains));
        }
    }

    bool dispatch(const EmailMessage& msg) {
        std::cout << "[SENT] " << msg.from << " -> " << msg.to 
                  << " : " << msg.subject << std::endl;
        audit_.emit("email_sent", msg.from + " -> " + msg.to);
        return true;
    }

    std::string extract_domain(const std::string& email) {
        auto pos = email.find('@');
        if (pos == std::string::npos) return "";
        return email.substr(pos + 1);
    }

    std::vector<std::string> parse_domain_list(const std::string& csv) {
        std::vector<std::string> result;
        size_t start = 0, end;
        while ((end = csv.find(',', start)) != std::string::npos) {
            result.push_back(csv.substr(start, end - start));
            start = end + 1;
        }
        if (start < csv.size()) result.push_back(csv.substr(start));
        return result;
    }

    AuditLog& audit_;
    RateLimiter limiter_;
    std::mutex domain_mtx_;
    std::unique_ptr<std::vector<std::string>> restricted_domains_;
};

class ServiceManager {
public:
    ServiceManager() : audit_(), email_service_(nullptr) {}

    void initialize(int rate_limit) {
        email_service_ = std::make_unique<EmailService>(audit_, rate_limit);
    }

    void reconfigure(int new_rate_limit) {
        email_service_ = std::make_unique<EmailService>(audit_, new_rate_limit);
    }

    bool send(const EmailMessage& msg) {
        if (!email_service_) return false;
        return email_service_->send_email(msg);
    }

    void trigger_policy_update(const std::string& policy) {
        audit_.emit("policy_change", policy);
    }

private:
    AuditLog audit_;
    std::unique_ptr<EmailService> email_service_;
};

int main() {
    ServiceManager mgr;
    mgr.initialize(10);

    EmailMessage msg{"alice@corp.com", "bob@external.com", "Hello", "Body", Role::USER};
    mgr.send(msg);

    mgr.trigger_policy_update("domains:external.com,evil.com");

    mgr.reconfigure(5);

    // This triggers use-after-free: old EmailService's callback still registered
    mgr.trigger_policy_update("reset_limits");

    mgr.send(msg);
    return 0;
}
